"""Softlock detector for tiny adventure games.

Game model
----------
A game is a spec dict:

    locations : ignored explicitly -- implied by everything else
    start     : starting location name
    win       : location that counts as winning
    two_way   : [(a, b), ...]            free passages, walkable both ways
    one_way   : [(a, b), ...]            one-way passages (drops, slides, pits)
    items     : {item_name: location}    pickups lying around (one copy each)
    doors     : {name: {"between": [a, b],
                        "key": item_name,
                        "consumes": bool}}   -- a consumed key is gone for good

A *state* is (location, frozenset(inventory), frozenset(open_doors)).
The full state space is finite, so the analyzer always terminates.

A softlock is any reachable state from which no win state is reachable.
"""

from collections import deque

# --------------------------------------------------------------------------
# Inline game spec
# --------------------------------------------------------------------------
#
# Story: you start with a brass key.  In the hall there are TWO doors that
# both demand the brass key, and it is CONSUMED on use:
#
#   treasure_door -> the win room          (the right choice)
#   closet_door   -> a closet holding a useless silver key (the wrong choice;
#                    the cellar it opens is a red herring, its door does not
#                    consume the silver key)
#
# There is also a one-way drop from the hall into a pit -- survivable,
# there is a ladder out, so it is scary but not a softlock by itself.

SPEC = {
    "start": "start",
    "win": "treasure",
    "two_way": [
        ("start", "hall"),
    ],
    "one_way": [
        ("hall", "pit"),    # one-way drop into the pit room
        ("pit", "start"),   # ladder back out (still one-way)
    ],
    "items": {
        "brass_key": "start",
        "silver_key": "closet",
    },
    "doors": {
        "treasure_door": {"between": ("hall", "treasure"), "key": "brass_key", "consumes": True},
        "closet_door":   {"between": ("hall", "closet"),   "key": "brass_key", "consumes": True},
        "cellar_door":   {"between": ("hall", "cellar"),   "key": "silver_key", "consumes": False},
    },
}


# --------------------------------------------------------------------------
# State machine
# --------------------------------------------------------------------------

def initial_state(spec):
    return (spec["start"], frozenset(), frozenset())


def is_win(spec, state):
    return state[0] == spec["win"]


def transitions(spec, state):
    """Yield (next_state, action_label) pairs from `state`."""
    loc, inv, opened = state
    out = []

    def add(nloc, ninv, nopened, label):
        out.append(((nloc, ninv, nopened), label))

    for a, b in spec["two_way"]:
        if loc == a:
            add(b, inv, opened, f"walk {a}->{b}")
        elif loc == b:
            add(a, inv, opened, f"walk {b}->{a}")
    for a, b in spec["one_way"]:
        if loc == a:
            add(b, inv, opened, f"drop {a}->{b}")

    for item, where in spec["items"].items():
        if where == loc and item not in inv:
            add(loc, inv | {item}, opened, f"take {item}")

    for name, door in spec["doors"].items():
        a, b = door["between"]
        if name not in opened and loc in (a, b) and door["key"] in inv:
            ninv = inv - {door["key"]} if door["consumes"] else inv
            add(loc, ninv, opened | {name}, f"unlock {name} ({'consumes' if door['consumes'] else 'keeps'} {door['key']})")

    for name in opened:
        a, b = spec["doors"][name]["between"]
        if loc == a:
            add(b, inv, opened, f"pass {name}")
        elif loc == b:
            add(a, inv, opened, f"pass {name}")

    return out


# --------------------------------------------------------------------------
# Analyzer
# --------------------------------------------------------------------------

def analyze(spec):
    """Explore the full reachable state space.

    Returns a dict with:
      reachable      : frozenset of all reachable states
      edges          : {state: [(next_state, action), ...]}
      win_states     : frozenset of reachable win states
      softlocks      : sorted list of (state, description) -- reachable states
                       from which no win state is reachable
      steps_to_softlock : {state: shortest action sequence reaching it}
    """
    start = initial_state(spec)
    edges = {}
    queue = deque([start])
    reachable = {start}
    first_action = {start: []}

    while queue:
        s = queue.popleft()
        succ = transitions(spec, s)
        edges[s] = succ
        for nxt, action in succ:
            if nxt not in reachable:
                reachable.add(nxt)
                first_action[nxt] = first_action[s] + [action]
                queue.append(nxt)

    win_states = frozenset(s for s in reachable if is_win(spec, s))
    if not win_states:
        softlocked = set(reachable) - {start} | {start}  # everything is lost
        softlocked = set(reachable)
    else:
        # Backward reachability from all win states.
        preds = {s: [] for s in reachable}
        for s in reachable:
            for nxt, _ in edges[s]:
                preds[nxt].append(s)
        can_win = set(win_states)
        stack = list(win_states)
        while stack:
            s = stack.pop()
            for p in preds[s]:
                if p not in can_win:
                    can_win.add(p)
                    stack.append(p)
        softlocked = set(reachable) - can_win

    report = sorted(
        ((s, describe_state(spec, s)) for s in softlocked),
        key=lambda t: (t[0][0], sorted(t[0][1]), sorted(t[0][2])),
    )
    return {
        "reachable": frozenset(reachable),
        "edges": edges,
        "win_states": win_states,
        "softlocks": report,
        "steps_to_softlock": {s: first_action[s] for s, _ in report},
    }


def describe_state(spec, state):
    loc, inv, opened = state
    doors = ", ".join(
        f"{name}: {'open' if name in opened else 'shut'}"
        for name in spec["doors"]
    )
    return (f"(location='{loc}', inventory={sorted(inv)}, "
            f"doors={{{doors}}})")


def report(spec):
    """Human-readable report for CLI use."""
    res = analyze(spec)
    lines = []
    lines.append(f"reachable states : {len(res['reachable'])}")
    lines.append(f"win states       : {len(res['win_states'])}")
    lines.append(f"SOFTLOCKS        : {len(res['softlocks'])}")
    for state, desc in res["softlocks"]:
        steps = res["steps_to_softlock"][state]
        lines.append(f"  SOFTLOCK {desc}")
        lines.append(f"    reached via: {'; '.join(steps) if steps else '(already at start)'}")
    return "\n".join(lines)


if __name__ == "__main__":
    print(report(SPEC))

